const run = $input.first().json;
const items = run.items || [];
const processed = Number(run.processed || 0);
const claimed = Number(run.claimed || 0);
const failed = items.filter((item) => item.status === 'failed');
const ready = items.filter((item) => item.status === 'packet_ready');
const review = items.filter((item) => item.status === 'manual_review' || item.status === 'scored');
const rejected = items.filter((item) => item.status === 'rejected');
const shouldNotify = processed > 0 || failed.length > 0;
const lines = [
  '**CareerSite queue worker**',
  `Claimed: ${claimed} | Processed: ${processed}`,
  `Packet ready: ${ready.length} | Review: ${review.length} | Rejected: ${rejected.length} | Failed: ${failed.length}`,
];
for (const item of items.slice(0, 5)) {
  const pipeline = item.pipeline_result || {};
  const exportResult = item.export_result || {};
  const company = pipeline.company || 'Unknown company';
  const title = pipeline.title || 'Unknown role';
  const score = pipeline.base_score === undefined ? 'N/A' : `${pipeline.base_score}%`;
  const path = exportResult.tailored_resume_pdf_path || exportResult.tailored_resume_html_path || exportResult.packet_folder_path || '';
  lines.push(`- ${item.status}: ${company} | ${title} | ${score}${path ? ` | ${path}` : ''}`);
  if (item.error) lines.push(`  Error: ${item.error}`);
}
return [{ json: { ...run, should_notify: shouldNotify, discord_content: lines.join('\n').slice(0, 1900) } }];
